"""RESULTS.md, rendered from the results payload. Generated, never hand-edited."""

from __future__ import annotations

from typing import Any

GENERATED_BY = (
    "Generated by `python -m redrun eval`. Do not edit this file by hand: the next "
    "run overwrites it. The matching machine-readable payload sits beside it in "
    "`eval/results/`."
)


def _pct(value: float | None) -> str:
    return "n/a" if value is None else f"{value * 100:.1f}%"


def _counts(hits: int | None, total: int) -> str:
    if hits is None or not total:
        return "n/a"
    return f"{hits}/{total}"


def _num(value: Any) -> str:
    if value is None:
        return "n/a"
    if isinstance(value, float):
        return f"{value:.2f}"
    return str(value)


def _tick(flag: bool | None) -> str:
    if flag is None:
        return "n/a"
    return "yes" if flag else "no"


def meta_block(payload: dict[str, Any]) -> str:
    meta = payload["meta"]
    every = meta.get("agent_models") or []
    recorded = [name for name in every if not str(name).startswith("sample/")]
    labels = ", ".join(f"`{name}`" for name in (meta.get("agent_lane_labels") or every)) or "none"
    replayed = meta["mode"] == "replay"
    agent_line = (
        "- agent: Markovian investigator → skeptic → citation guard → computed confidence"
    )
    if recorded:
        agent_line += f", recorded live on {', '.join(f'`{m}`' for m in recorded)}"
    lines = [
        f"- run: `{meta['timestamp']}`",
        f"- mode: `{meta['mode']}` · split: `{meta['split']}` · seed: `{meta['seed']}`",
        f"- cases: {meta['case_count']} from `{meta['cases_path']}`",
        agent_line,
        f"- baseline: one `{meta.get('baseline_model') or 'fast lane'}` call on the last "
        f"{meta['baseline_lines']} redacted log lines",
        f"- git: `{meta.get('git_sha') or 'unknown'}`",
    ]
    if replayed:
        detail = (
            "Every figure below is the one the model produced when the sample was "
            "recorded live: the agent's steps come from `samples/<case>/llm/steps.json`, "
            "and the baseline is its recorded reply. No model was called for this run, so "
            "a latency of 97s is the recorded model's own time and not this run's."
        )
        if recorded:
            lines.append(f"- {detail}")
        else:
            lines.append(
                f"- {detail} These samples were recorded before the recorder kept the "
                f"model id, so the agent's {labels} are the replay client's lane names, "
                "not models. The baseline's model is recorded and named above."
            )
    else:
        lines.append(
            "- both systems ran for real in this run: the agent against its provider and "
            "the baseline against the fast lane."
        )
    if meta.get("notes"):
        lines.append(f"- {meta['notes']}")
    return "\n".join(lines)


def totals_table(payload: dict[str, Any]) -> str:
    rows = [
        "| split | cases | agent cause | agent keywords | agent citations | guard "
        "interventions | baseline cause | baseline keywords |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for name, summary in payload["summaries"].items():
        agent = summary["agent"]
        baseline = summary["baseline"]
        rows.append(
            "| {split} | {cases} | {ac} ({ap}) | {ak} ({akp}) | {acite} | {guard} | {bc} ({bp}) | {bk} ({bkp}) |".format(
                split=name,
                cases=agent["cases"],
                ac=_counts(agent["cause_hits"], agent["cases"]),
                ap=_pct(agent["cause_accuracy"]),
                ak=_counts(agent["keyword_hits"], agent["cases"]),
                akp=_pct(agent["keyword_accuracy"]),
                acite=(
                    "n/a"
                    if agent["citation_pass_rate"] is None
                    else f"{agent['citation_pass']}/{agent['citation_evaluated']} ({_pct(agent['citation_pass_rate'])})"
                ),
                guard=agent["guard_interventions"],
                bc=_counts(baseline["cause_hits"], baseline["cases"]),
                bp=_pct(baseline["cause_accuracy"]),
                bk=_counts(baseline["keyword_hits"], baseline["cases"]),
                bkp=_pct(baseline["keyword_accuracy"]),
            )
        )
    return "\n".join(rows)


def abstention_table(payload: dict[str, Any]) -> str:
    rows = [
        "| split | system | answered with a cause | right when it answered |",
        "| --- | --- | --- | --- |",
    ]
    for name, summary in payload["summaries"].items():
        for system in ("agent", "baseline"):
            entry = summary[system]
            if not entry["cases"]:
                continue
            rows.append(
                f"| {name} | {system} | {entry['answered']}/{entry['cases']} | "
                f"{entry['answered_correct']}/{entry['answered']} "
                f"({_pct(entry['answered_precision'])}) |"
            )
    return "\n".join(rows)


def calibration_table(payload: dict[str, Any]) -> str:
    rows = [
        "| split | agent mean confidence (correct) | agent mean confidence (wrong) | difference |",
        "| --- | --- | --- | --- |",
    ]
    for name, summary in payload["summaries"].items():
        calibration = summary["agent"]["calibration"]
        correct, wrong = calibration["correct"], calibration["wrong"]
        gap = "n/a" if correct is None or wrong is None else f"{correct - wrong:+.2f}"
        rows.append(
            f"| {name} | {_num(correct)} ({calibration['correct_cases']} cases) | "
            f"{_num(wrong)} ({calibration['wrong_cases']} cases) | {gap} |"
        )
    return "\n".join(rows)


def cost_table(payload: dict[str, Any]) -> str:
    rows = [
        "| split | system | latency p50 (ms) | latency p95 (ms) | tokens in | tokens out |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for name, summary in payload["summaries"].items():
        for system in ("agent", "baseline"):
            entry = summary[system]
            rows.append(
                f"| {name} | {system} | {_num(entry['latency_p50_ms'])} | "
                f"{_num(entry['latency_p95_ms'])} | {entry['tokens_in']} | {entry['tokens_out']} |"
            )
    return "\n".join(rows)


def confusion_table(payload: dict[str, Any], system: str) -> str:
    confusion: dict[str, dict[str, int]] = payload["summaries"]["all"][system]["confusion"]
    if not confusion:
        return "_no observations_"
    predicted = sorted({value for row in confusion.values() for value in row})
    header = "| expected \\ predicted | " + " | ".join(predicted) + " |"
    rows = [header, "| --- | " + " | ".join("---" for _ in predicted) + " |"]
    for expected in sorted(confusion):
        cells = [str(confusion[expected].get(name, 0)) for name in predicted]
        rows.append(f"| {expected} | " + " | ".join(cells) + " |")
    return "\n".join(rows)


def per_case_table(payload: dict[str, Any]) -> str:
    rows = [
        "| case | expected | split | constructed | agent | agent conf | agent keywords "
        "| baseline | baseline keywords |",
        "| --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for row in payload["rows"]:
        agent = row.get("agent")
        baseline = row.get("baseline")
        if agent is None:
            agent_cell = f"pending ({row.get('path', 'not run')})"
        else:
            agent_cell = f"{agent['cause']} {'✓' if agent['category_ok'] else '✗'}"
        rows.append(
            "| {id} | {expected} | {split} | {constructed} | {agent} | {conf} | {akw} | "
            "{base} | {bkw} |".format(
                id=row["id"],
                expected=row["expected_cause"],
                split=row["split"],
                constructed="yes" if row["constructed"] else "no",
                agent=agent_cell,
                conf="n/a" if agent is None else f"{agent['confidence']:.2f}",
                akw="n/a" if agent is None else (_tick(agent["keywords_ok"]) + (
                    "" if agent["keywords_ok"] else f" (missing {', '.join(agent['keywords_missing'])})"
                )),
                base=(
                    "not recorded"
                    if baseline is None
                    else f"{baseline['cause']} {'✓' if baseline['category_ok'] else '✗'}"
                ),
                bkw=(
                    "not recorded"
                    if baseline is None
                    else (_tick(baseline["keywords_ok"]) + (
                        "" if baseline["keywords_ok"] else f" (missing {', '.join(baseline['keywords_missing'])})"
                    ))
                ),
            )
        )
    return "\n".join(rows)


def pending_block(payload: dict[str, Any]) -> str:
    if not payload["pending"]:
        return (
            "None. Every case in this run has a recorded model sequence to replay, so "
            "nothing is missing a recording. This says the samples are complete, not that "
            "a model ran here."
        )
    rows = ["| case | split | why | rules-only verdict (diagnostic) |", "| --- | --- | --- | --- |"]
    for item in payload["pending"]:
        rows.append(
            f"| {item['id']} | {item['split']} | {item['reason']} | "
            f"{item.get('rules_cause') or 'n/a'} |"
        )
    return "\n".join(rows)


def baseline_pending_block(payload: dict[str, Any]) -> str:
    items = payload.get("baseline_pending") or []
    if not items:
        return "None. Every case in this run has a recorded baseline reply to replay."
    rows = ["| case | split | why |", "| --- | --- | --- |"]
    for item in items:
        rows.append(f"| {item['id']} | {item['split']} | {item['reason']} |")
    return "\n".join(rows)


def render(payload: dict[str, Any]) -> str:
    meta = payload["meta"]
    parts = [
        "# RedRun evaluation results",
        "",
        GENERATED_BY,
        "",
        "## How this was run",
        "",
        meta_block(payload),
        "",
        "## Totals",
        "",
        totals_table(payload),
        "",
        "Accuracy counts the cause the system returned against the cause the case was "
        "built to have. A keyword hit means every one of that case's root-cause keywords "
        "appears in the returned explanation. Citation validity is the share of verdicts "
        "that satisfy the citation guard; the baseline is not asked to cite, so it is n/a.",
        "",
        "Each row counts only what ran: a case with no recording is left out of that "
        "system's denominator and listed under the pending tables at the end.",
        "",
        "## Abstention",
        "",
        "`unknown` is a real answer, so it is not a wrong one. This is what each system "
        "said when it committed to a cause, which is the number to read next to accuracy.",
        "",
        abstention_table(payload),
        "",
        "## Calibration",
        "",
        "A useful confidence number is higher when the answer is right. The agent's is "
        "computed from named signals; the baseline emits none, so it has no column here.",
        "",
        calibration_table(payload),
        "",
        "## Cost",
        "",
        "Latency is the model's own, summed over its steps, so a replay reports what the "
        "investigation actually cost rather than how long it took to read the fixtures.",
        "",
        cost_table(payload),
        "",
        f"## Confusion matrix, agent (`{meta['mode']}`)",
        "",
        confusion_table(payload, "agent"),
        "",
        "## Confusion matrix, baseline",
        "",
        confusion_table(payload, "baseline"),
        "",
        "## Per case",
        "",
        per_case_table(payload),
        "",
        "## Cases whose recording has no model half",
        "",
        pending_block(payload),
        "",
        "## Cases without a recorded baseline",
        "",
        baseline_pending_block(payload),
        "",
    ]
    return "\n".join(parts)
